 "content": "def transform(grid):
    """Extract the 4x4 pattern shared by repeated object motifs."""
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx]
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            objects.append(cells)
    matches = []
    for cells in objects:
        r0 = min(r for r, _ in cells)
        r1 = max(r for r, _ in cells)
        c0 = min(c for _, c in cells)
        c1 = max(c for _, c in cells)
        if r1 - r0 + 1 == 4 and c1 - c0 + 1 == 4:
            matches.append([[grid[r][c] for c in range(c0, c1 + 1)]
                            for r in range(r0, r1 + 1)])
    if matches:
        return matches[0]
    raise ValueError("No intact 4x4 object found")
