 "content": "def transform(grid):
    """Return the common 4x4 shape of the repeated foreground glyphs."""
    h, w = len(grid), len(grid[0])
    glyphs = []
    # Each object is one 4x4 glyph, and diagonal contact may merge objects.
    seen = set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        ny, nx = y + dy, x + dx
                        if (0 <= ny < h and 0 <= nx < w and grid[ny][nx]
                                and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            r0, r1 = min(y for y, _ in cells), max(y for y, _ in cells)
            c0, c1 = min(x for _, x in cells), max(x for _, x in cells)
            if r1 - r0 == 3 and c1 - c0 == 3:
                glyphs.append([[grid[y][x] for x in range(c0, c1 + 1)]
                               for y in range(r0, r1 + 1)])
    # In these puzzles the identical glyph is repeated; select the most
    # frequent 4x4 pattern (ties use first reading order).
    if glyphs:
        return max(glyphs, key=lambda g: sum(g == other for other in glyphs))
    raise ValueError("No 4x4 glyph found")
