    """Extract the common foreground motif from 4x4 crops of the scene."""
    h = len(grid)
    w = max(len(row) for row in grid)
    a = [row + [0] * (w - len(row)) for row in grid]
    crops = []
    for r in range(h - 3):
        for c in range(w - 3):
            crop = [row[c:c + 4] for row in a[r:r + 4]]
            n = sum(v != 0 for row in crop for v in row)
            if 0 < n < 16:
                crops.append((n, crop))
    # Most frequent crop pattern (scan order breaks ties).
    return max((crop for _, crop in crops),
               key=lambda g: sum(g == other for _, other in crops))
