 "content": "def transform(grid):
    """Extract the 4x4 shape that occurs most often as a window in the grid."""
    h = len(grid)
    w = max(map(len, grid))
    a = [row + [0] * (w - len(row)) for row in grid]
    counts = {}
    for r in range(h - 3):
        for c in range(w - 3):
            crop = tuple(tuple(a[y][c:c + 4]) for y in range(r, r + 4))
            if any(v for row in crop for v in row):
                counts[crop] = counts.get(crop, 0) + 1
    best = max(counts, key=counts.get)
    return [list(row) for row in best]
