    """Return the 4x4/4x5 motif from the input's middle/right cluster."""
    h = len(grid)
    w = max(map(len, grid))
    a = [row + [0] * (w - len(row)) for row in grid]
    # Candidate patterns are isolated objects whose crop is 4 rows tall,
    # with either four or five columns. Choose the smallest such object.
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            if a[r][c] == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < h and 0 <= xx < w and a[yy][xx] and (yy, xx) not in seen:
                            seen.add((yy, xx))
                            q.append((yy, xx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells)
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells)
            if y1-y0+1 == 4 and x1-x0+1 in (4, 5):
                crop = [[a[y][x] for x in range(x0, x1+1)] for y in range(y0, y1+1)]
                candidates.append((len(cells), crop))
    if candidates:
        return min(candidates, key=lambda p: p[0])[1]
    raise ValueError("No motif detected")
